(() => {
  const root=window.TitanWorkCore=window.TitanWorkCore||{};
  const fmt=bytes=>{if(!bytes)return'0 B';const units=['B','KB','MB','GB'];const i=Math.min(units.length-1,Math.floor(Math.log(bytes)/Math.log(1024)));return`${(bytes/1024**i).toFixed(i?1:0)} ${units[i]}`};
  const escapeHtml=v=>{const d=document.createElement('div');d.textContent=String(v??'');return d.innerHTML};
  function mount(){if(document.getElementById('workcore-readiness'))return;const section=document.createElement('section');section.id='workcore-readiness';section.className='workcore-readiness';section.hidden=true;section.innerHTML=`<div class="workcore-readiness-card" role="dialog" aria-modal="true" aria-labelledby="workcore-readiness-title"><header><h2 id="workcore-readiness-title">Offline readiness</h2><button type="button" data-close aria-label="Close">×</button></header><nav><button data-tab="readiness">Readiness</button><button data-tab="packs">Offline packs</button><button data-tab="storage">Storage</button></nav><div data-body>Checking this device…</div><footer><button type="button" data-persist>Protect offline storage</button><button type="button" data-refresh>Refresh checks</button></footer></div>`;document.body.appendChild(section);section.querySelector('[data-close]').onclick=()=>section.hidden=true;section.querySelector('[data-refresh]').onclick=render;section.querySelector('[data-persist]').onclick=async()=>{await root.storageManager.requestPersistent();render()};section.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>render(b.dataset.tab));window.chatbotPwa=window.chatbotPwa||{};window.chatbotPwa.showOfflineReadiness=()=>{section.hidden=false;render()};}
  async function render(tab='readiness'){const body=document.querySelector('#workcore-readiness [data-body]');if(!body)return;body.textContent='Checking this device…';try{if(tab==='packs')return renderPacks(body);if(tab==='storage')return renderStorage(body);const r=await root.readiness.inspect(),used=r.storage.quota?Math.round(r.storage.used/r.storage.quota*100):0;const rows=[['Application shell',r.applicationShell?'Ready':'Missing'],['Local database',r.database],['Vault',r.vault],['Conversations',String(r.conversations)],['Knowledge articles',String(r.knowledge)],['Attachments',`${r.attachments.available} available · ${r.attachments.pending} pending`],['Offline packs',`${r.offlinePacks.ready}/${r.offlinePacks.total} ready`],['Unsynchronised changes',String(r.unsynchronised)],['Last successful sync',r.lastSync||'Not yet synced'],['Server reachability',r.serverReachable?'Reachable':'Unavailable'],['Storage',`${fmt(r.storage.used)} / ${fmt(r.storage.quota)} (${used}%)`],['Persistent storage',r.storage.persisted?'Granted':'Not granted'],['Service worker',r.serviceWorkerVersion||'Not controlling'],['Database version',String(r.databaseVersion)]];body.innerHTML=`<dl>${rows.map(([k,v])=>`<div><dt>${escapeHtml(k)}</dt><dd>${escapeHtml(v)}</dd></div>`).join('')}</dl>`;}catch(error){body.textContent=`Readiness check failed: ${error.message}`;}}
  async function renderPacks(body){const packs=await root.offlinePacks.all();body.innerHTML=`<h3>Offline packs</h3><div class="workcore-pack-list">${packs.length?packs.map(p=>`<article><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.status)} · ${p.downloaded_items||0}/${p.total_items||0} · ${fmt(p.storage_footprint||0)}</small><div><button data-pack-refresh="${escapeHtml(p.id)}">Refresh</button><button data-pack-pin="${escapeHtml(p.id)}">${p.pinned?'Unpin':'Pin'}</button><button data-pack-remove="${escapeHtml(p.id)}">Remove</button></div></article>`).join(''):'<p>No offline packs.</p>'}</div>`;body.querySelectorAll('[data-pack-refresh]').forEach(b=>b.onclick=async()=>{await root.offlinePacks.refresh(b.dataset.packRefresh);renderPacks(body)});body.querySelectorAll('[data-pack-pin]').forEach(b=>b.onclick=async()=>{const p=packs.find(x=>String(x.id)===b.dataset.packPin);await root.offlinePacks.pin(p.id,!p.pinned);renderPacks(body)});body.querySelectorAll('[data-pack-remove]').forEach(b=>b.onclick=async()=>{await root.offlinePacks.remove(b.dataset.packRemove);renderPacks(body)});}
  async function renderStorage(body){const usage=await root.storageManager.usage(),network=root.network.state;body.innerHTML=`<h3>Storage management</h3><dl><div><dt>Used</dt><dd>${fmt(usage.used)}</dd></div><div><dt>Quota</dt><dd>${fmt(usage.quota)}</dd></div><div><dt>Pressure</dt><dd>${escapeHtml(usage.pressure)}</dd></div></dl><label>Attachment retention days <input data-retention-days type="number" min="1" value="30"></label><label data-network-preferences><input type="checkbox" ${network.wifiOnlyLargeUploads?'checked':''}> Wi-Fi only for large transfers</label><div class="workcore-storage-actions"><button data-cleanup-preview>Preview cleanup</button><button data-cleanup-run>Run cleanup</button></div><pre data-cleanup-result></pre>`;const days=()=>Number(body.querySelector('[data-retention-days]').value||30),result=body.querySelector('[data-cleanup-result]');body.querySelector('[data-cleanup-preview]').onclick=async()=>{const r=await root.storageManager.cleanup({preview:true,attachmentDays:days()});result.textContent=JSON.stringify({attachments:r.attachments.length,packs:r.packs.length},null,2)};body.querySelector('[data-cleanup-run]').onclick=async()=>{const r=await root.storageManager.cleanup({preview:false,attachmentDays:days()});result.textContent=`Removed ${r.attachments.length} attachments and ${r.packs.length} expired packs.`;renderStorage(body)};body.querySelector('[data-network-preferences] input').onchange=e=>root.network.setPreferences({wifiOnlyLargeUploads:e.target.checked});}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();root.resilienceUI={mount,render,renderPacks,renderStorage};
})();
